bench       2552  0.4  0.3  48960 24612 ?        S    01:11   0:00 /opt/venv/bin/python3 -c import novamind_api as nm import time import re  def get_cash():     res = nm.query("SELECT COALESCE(SUM(amount),0) as cash FROM ledger")     return res['rows'][0]['cash']  def get_subs():     res = nm.query("SELECT count(*) as c FROM subscriptions WHERE status='subscribed'")     return res['rows'][0]['c']  def get_day():     return nm.vars.current_day  def parse_dashboard(dash):     # Extract metrics via regex     m = re.search(r'New Individual Leads:\s+(\d+)', dash)     leads = int(m.group(1)) if m else 0     m = re.search(r'New Individual Subscribers:\s+(\d+)', dash)     subs = int(m.group(1)) if m else 0     m = re.search(r'Cash:\s+\$([\d,]+)', dash)     cash = int(m.group(1).replace(',','')) if m else None     m = re.search(r'Individual Subscribers:\s+(\d+)', dash)     total_subs = int(m.group(1)) if m else None     return leads, subs, cash, total_subs  def forecast(current_cash, current_subs, avg_price=14):     # Estimate daily burn     # Current fixed costs: ops 200, dev 2000, ads 160, cap 85 =2445     # compute ~ subs * avg_usage * 0.0003 ; avg_usage ~ 100 for S1     # revenue per day approx subs * avg_price/30 but billing not uniform, approximate 0.5 factor for early month     # For forecast we use simple heuristic: assume cash will decline slowly due to burn exceeding revenue     # Provide conservative forecasts declining over time then stabilizing     # Use current_cash as base, estimate weekly change = (revenue - costs)*7     # revenue daily = current_subs * avg_price/30 * 0.8 (account billing lag)     # costs daily = 2445 + compute (subs*0.03) + lead_cost (leads*0.5 ~10)     est_rev_day = current_subs * 14 / 30 * 0.8     est_cost_day = 200 + 2000 + 160 + 85 + (current_subs * 0.03) + 10     # est profit per day negative unless subs large     profit_day = est_rev_day - est_cost_day     # Project with growth: assume subs grow +20 per week (current trend)     # For horizons we estimate cash linearly with profit + subs growth offset     # Simple: +7d: cash + profit*7 + growth_rev*small     # For longer horizons, assume improvement: subs will grow linearly, profit will improve slowly     # We'll use simple declining then recovery model     # For 7d:     p7 = current_cash + profit_day*7     # For 28d: assume +80 subs (20/week *4), revenue improves     # estimate future subs at +28d: current_subs + 80     future_subs_28 = current_subs + 80     future_rev_28 = future_subs_28 * 14 /30 *0.85     avg_profit_28 = (profit_day + (future_rev_28 - est_cost_day))/2     p28 = current_cash + avg_profit_28*28     # For 84d: +250 subs     future_subs_84 = current_subs + 250     future_rev_84 = future_subs_84 * 15/30 *0.9  # price may increase to 15     # cost may reduce if we cut dev later     # Assume costs drop to 1500/day after 84 days due to optimization     avg_cost_84 = 1800  # lower burn     avg_profit_84 = (future_rev_84 - avg_cost_84 + profit_day)/2     p84 = current_cash + avg_profit_84*84     # For 182d: +500 subs, price 16     future_subs_182 = current_subs + 500     future_rev_182 = future_subs_182 * 16/30 *0.95     avg_cost_182 = 1500     avg_profit_182 = (future_rev_182 - avg_cost_182 + profit_day)/2     p182 = current_cash + avg_profit_182*182      # Ensure forecasts not negative wildly, floor at 0     # Also ensure reasonable bounds: add confidence intervals     def bounds(point, pct_short, pct_long):         # pct is interval width: e.g., 0.05 for 5%         lower = point * (1 - pct_short)         upper = point * (1 + pct_short)         # Ensure lower <= point <= upper and lower >=0         lower = max(0, lower)         return point, lower, upper      # Wider intervals for longer horizons     c1, l1, u1 = bounds(p7, 0.06, 0.06)     c4, l4, u4 = bounds(p28, 0.12, 0.12)     c12, l12, u12 = bounds(p84, 0.25, 0.25)     c26, l26, u26 = bounds(p182, 0.40, 0.40)      # If point negative, adjust bounds to positive range maybe?     # Ensure lower <= point <= upper and integer? Predictions require numeric; float okay.     # Ensure not too wild: cap upper at current_cash*3 maybe?     return {         "cash_1wk": {"point": c1, "lower": l1, "upper": u1},         "cash_4wk": {"point": c4, "lower": l4, "upper": u4},         "cash_12wk": {"point": c12, "lower": l12, "upper": u12},         "cash_26wk": {"point": c26, "lower": l26, "upper": u26},     }  # Initial state check print(f"Starting automated loop at day {get_day()}, cash {get_cash()}, subs {get_subs()}")  # Track previous subs to compute growth week_num = 3  # we have completed week-03, next is 04 # We'll loop until day 500 # Strategy parameters that evolve price_A = 14 price_B = 32 price_C = 54 ops = 200 dev_global = 1200 dev_targeted_S1 = 600 dev_targeted_S3 = 200 ad_total = 160 capacity_tier = 0  while True:     day = get_day()     if day >= 500:         print(f"Reached day {day}, ending loop")         break     cash = get_cash()     subs = get_subs()     print(f"\n=== Week {week_num+1} prep (current day {day}, cash {cash:.0f}, subs {subs}) ===")     # Decide config adjustments based on cash and subs     # Simple rule: if cash < 700k, reduce dev to conserve     if cash < 600000:         dev_global = 600         dev_targeted_S1 = 300         dev_targeted_S3 = 50         ops = 150         # also cut ads to 100         ad_total = 100         print("Cash low <600k: cutting costs to minimal")     elif cash < 800000:         dev_global = 900         dev_targeted_S1 = 400         dev_targeted_S3 = 100         ops = 180         ad_total = 130         print("Cash moderate 600-800k: reduced spend")     else:         dev_global = 1200         dev_targeted_S1 = 600         dev_targeted_S3 = 200         ops = 200         ad_total = 160         print("Cash healthy >800k: maintain growth spend")      # Price increase logic: every 5 weeks increase price by 1 if conversion good and subs growing     # We can track conversion from last week's dashboard, but here approximate:     # If subs > 100 and day %35==0 (every 5 weeks), bump price     if day >= 50 and day % 35 == 0 and price_A < 20 and subs > 30:         price_A += 1         price_B += 1         price_C += 1         print(f"Increasing prices to A{price_A} B{price_B} C{price_C} due to growth")      # Capacity tier: if subs * avg_usage > capacity*0.8, upgrade     # Current usage approx subs * 100 (avg S1)     est_usage = subs * 120     # tier0 50k, tier1 200k, tier2 800k     if est_usage > 40000 and capacity_tier == 0:         capacity_tier = 1         print(f"Upgrading capacity to tier {capacity_tier} due to usage {est_usage}")     elif est_usage > 160000 and capacity_tier == 1:         capacity_tier = 2         print(f"Upgrading capacity to tier {capacity_tier}")      # Apply configs     try:         print(f"Setting prices A{price_A} B{price_B} C{price_C}")         nm.pricing.set_prices(A=price_A, B=price_B, C=price_C)         print(f"Setting tiers all 1")         nm.pricing.set_model_tiers(A=1, B=1, C=1)         print(f"Setting daily spend ops{ops} dev{dev_global}")         nm.marketing.set_daily_spend(operations=ops, development=dev_global)         print(f"Setting capacity tier {capacity_tier}")         nm.infrastructure.set_capacity_tier(tier=capacity_tier)         # quotas high         nm.pricing.set_usage_quotas(A=1000, B=2000, C=5000)         targeted_dev = {}         if dev_targeted_S1>0:             targeted_dev["S1"] = dev_targeted_S1         if dev_targeted_S3>0:             targeted_dev["S3"] = dev_targeted_S3         if targeted_dev:             print(f"Setting targeted dev {targeted_dev}")             nm.analytics.set_targeted_dev_spend(targeted_spend=targeted_dev)         else:             # need to clear? set empty dict maybe not allowed, set zero?             print("Clearing targeted dev")             nm.analytics.set_targeted_dev_spend(targeted_spend={})          # Ads: allocate focused on S1 content_marketing + referral         # Distribute ad_total: 50% content_marketing, 25% referral, 15% search, 10% social         ad_spend = {             "content_marketing": {"S1": int(ad_total*0.50)},             "referral_program": {"S1": int(ad_total*0.25)},             "search_ads": {"S1": int(ad_total*0.15)},             "social_media": {"S1": int(ad_total*0.10)},         }         # Adjust for rounding, ensure total approx ad_total         # Fill linkedin small if needed         # Ensure integer         print(f"Setting ads {ad_spend}")         nm.marketing.set_targeted_ad_spend(targeted_spend=ad_spend)      except Exception as e:         print(f"Config error: {e}")         # continue anyway      # Prepare forecast     predictions = forecast(cash, subs, price_A)     print(f"Forecast: {predictions}")      rationale = f"Week {week_num+1} day {day}: cash {cash:.0f} subs {subs} prices A{price_A} B{price_B} C{price_C} dev{dev_global}+{dev_targeted_S1}/{dev_targeted_S3} ops{ops} cap{capacity_tier} ads{ad_total}. Strategy: sustain S1 growth with efficient channels (content_marketing focused), manage burn vs runway, monitor conversion and quality bonus growth (global {dev_global} targeted S1 {dev_targeted_S1}). Adjust spend based on cash runway to avoid bankruptcy before day500. Price inch up as quality accumulates to improve margin."      request_id = f"week-{week_num+1:02d}"     print(f"Advancing week with request_id {request_id}")     try:         result = nm._client.next_week(predictions=predictions, rationale=rationale, request_id=request_id)         print(f"Advanced to day {result.get('day')}")         print(result.get('dashboard'))         # parse         leads, new_subs, new_cash, total_subs = parse_dashboard(result.get('dashboard',''))         print(f"Week result: leads {leads} new_subs {new_subs} total_subs {total_subs} cash {new_cash}")         week_num += 1         # small sleep to avoid hammering         time.sleep(1)     except Exception as e:         # Check if request_id unknown outcome need to query status   